import {mathAnswerGuide,learningBadge} from './learning-polish.js';
import {DB,player,save,unlock,commitRound} from './data.js';
import {createInstructionGate} from './game-instructions.js';
import {SpellingSpeech} from './spelling-speech.js';
import {MathBoard} from './math-board.js';
import {SKILLS,WORLDS,MATH_SUBJECTS,mathSubject,gradeSubjects,gradeLabel,freshMath,skillById,CURRICULUM_SOURCE} from './math-curriculum.js';
import {MathSession,checkAnswer} from './math-core.js';
import {mathCover,mathWorldArt,mathVisual} from './math-art.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=a=>Array.isArray(a)?`(${a.join(', ')})`:String(a);
export function openMathQuest(host,{exit,notify=()=>{},ask=async()=>true,initialPage='setup',sessionFactory=o=>new MathSession(o)}={}){
 const q=s=>host.querySelector(s);const account=id=>{const p=player(id);p.mathQuest||=freshMath();return p.mathQuest;};let ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],grades=[account(DB.active).grade,account(ids[1]||ids[0]).grade],config={...account(DB.active).settings,multiplayer:'solo',skill:'mixed',subject:'all',world:0},page='setup',run=null,board=null,boardStates=[null,null],speech=null,paused=false,disposed=false,raf=0,last=performance.now(),remaining=0,elapsed=0,hints=0,stage=0,hinted=false,committed=false,answer='',tutorialStep=0,drag=null,feedback=null;
 const gate=createInstructionGate({game:'math',onBack:exit,onReview:()=>{const before=paused;paused=true;board?.cancel?.();speech?.cancel();return()=>{paused=before;last=performance.now();};}});
 function persist(){if(!save())notify('Progress could not be saved. Export a backup before closing.','error');}
 function stopBoard(){if(board){const i=config.multiplayer==='coop'?0:run?.turn||0;boardStates[i]=board.snapshot();board.dispose();board=null;}}
 function shell(body){stopBoard();window.scrollTo(0,0);host.innerHTML=`<section class="mq-app"><header class="mq-top"><button data-exit>← ARCADE</button><div><small>LITTLE BIG ARCADE</small><h1>Math Quest</h1></div><button data-help>How to Play</button><button data-progress>Progress</button></header>${body}</section>`;q('[data-exit]').onclick=async()=>{const previous=paused;paused=true;speech?.cancel();if(!run||run.phase==='finished'||await ask('Leave this adventure? Completed answers are saved.'))exit();else{paused=previous;last=performance.now();}};q('[data-help]').onclick=()=>{if(gate.acknowledged)gate.review();else gate.show({players:ids.slice(0,config.multiplayer==='solo'?1:2).filter(Boolean).map(id=>player(id).name),difficulty:config.difficulty,modeLabel:'Math Quest'},()=>{});};q('[data-progress]').onclick=()=>{if(run&&run.phase!=='finished'){if(page==='question')pause();else notify('Finish this quest or return to setup to review learning progress.');return;}progress();};}
 function options(list,value){return list.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('');}
 function setup(){page='setup';run=null;feedback=null;speech?.cancel();shell(`<div class="mq-welcome"><div class="mq-cover">${mathCover()}<h2>Big ideas start with a little curiosity.</h2><p>Explore, sketch, try again. Your notebook is part of every adventure.</p><div class="mq-world-mini">${WORLDS.map((w,i)=>`<span>${w.icon} ${w.name}</span>`).join('')}</div></div><div class="mq-card"><h2>Choose your quest</h2><div class="mq-form"><label>Play together<select data-multi>${options([['solo','Solo'],['turns','Two players · take turns'],['coop','Co-op · shared notebook']],config.multiplayer)}</select></label>${[0,1].map(i=>`<label data-person="${i}">Player ${i+1}<select data-profile="${i}">${options(DB.profiles.map(p=>[p.id,p.name]),ids[i])}</select></label><label data-grade-wrap="${i}">Player ${i+1} school grade<select data-grade="${i}">${options(SKILLS.map((_,g)=>[g,gradeLabel(g)]),grades[i])}</select></label>`).join('')}<label>Quest mode<select data-mode>${options([['adventure','Adventure worlds'],['practice','Practice a skill'],['mixed','Mixed Challenge'],['speed','Speed Challenge'],['homework','Homework Helper']],config.mode)}</select></label><label>Difficulty<select data-difficulty>${options(['Easy','Normal','Hard','Adaptive'].map(x=>[x,x]),config.difficulty)}</select></label><label>Questions per player<select data-count>${options([5,10,15,20].map(x=>[x,x]),config.count)}</select></label><label data-subject-wrap>Subject category<select data-subject></select></label><label data-topic-wrap>Practice skill<select data-topic></select></label><label><input type="checkbox" data-timer ${config.timer?'checked':''}> Use timer in Speed Challenge</label><label><input type="checkbox" data-keep ${config.keepInk?'checked':''}> Keep my writing between questions</label></div><div class="mq-curriculum-info" data-curriculum-summary></div><div class="mq-buttons"><button data-play class="mq-primary">PLAY →</button><button data-parent>Parent progress</button></div><p class="mq-note">Grade-specific NC skills · local saves · free device voices · no drawing recognition</p></div></div>`);const update=()=>{for(const el of host.querySelectorAll('[data-person="1"],[data-grade-wrap="1"]'))el.hidden=config.multiplayer==='solo';const isPractice=['practice','homework'].includes(config.mode);q('[data-topic-wrap]').hidden=!isPractice;q('[data-subject-wrap]').hidden=!isPractice;const all=SKILLS[grades[0]],subjects=gradeSubjects(grades[0]);if(!subjects.includes(config.subject))config.subject='all';q('[data-subject]').innerHTML=options([['all','All subjects'],...subjects.map(s=>[s,s])],config.subject);const skills=config.subject==='all'?all:all.filter(s=>mathSubject(s)===config.subject);if(!skills.some(s=>s.id===config.skill))config.skill='mixed';q('[data-topic]').innerHTML=options([['mixed',config.subject==='all'?'Mix all subjects':'Mix this subject']],config.skill)+MATH_SUBJECTS.filter(subject=>skills.some(s=>mathSubject(s)===subject)).map(subject=>`<optgroup label="${esc(subject)}">${options(skills.filter(s=>mathSubject(s)===subject).map(s=>[s.id,s.label]),config.skill)}</optgroup>`).join('');q('[data-curriculum-summary]').innerHTML=`<strong>${gradeLabel(grades[0])}: ${all.length} skills · ${subjects.length} subject categories</strong><p>${subjects.map(s=>esc(s)).join(' · ')}</p><small>Adaptive starts at your grade’s standard level, offers easier review after mistakes, and advances with independent answers.</small>`;};update();q('[data-multi]').onchange=e=>{config.multiplayer=e.target.value;update();};host.querySelectorAll('[data-profile]').forEach(el=>el.onchange=e=>{const i=+el.dataset.profile;ids[i]=e.target.value;grades[i]=account(ids[i]).grade;q(`[data-grade="${i}"]`).value=grades[i];update();});host.querySelectorAll('[data-grade]').forEach(el=>el.onchange=e=>{grades[+el.dataset.grade]=+e.target.value;config.skill='mixed';update();});q('[data-mode]').onchange=e=>{config.mode=e.target.value;update();};q('[data-difficulty]').onchange=e=>config.difficulty=e.target.value;q('[data-count]').onchange=e=>config.count=+e.target.value;q('[data-subject]').onchange=e=>{config.subject=e.target.value;config.skill='mixed';update();};q('[data-topic]').onchange=e=>config.skill=e.target.value;q('[data-timer]').onchange=e=>config.timer=e.target.checked;q('[data-keep]').onchange=e=>config.keepInk=e.target.checked;q('[data-parent]').onclick=()=>progress();q('[data-play]').onclick=()=>{if(config.multiplayer!=='solo'&&(!ids[1]||ids[0]===ids[1])){notify('Choose two different arcade profiles. Add another profile in the arcade if needed.');return;}const selected=ids.slice(0,config.multiplayer==='solo'?1:2);selected.forEach((id,i)=>{account(id).grade=grades[i];account(id).settings={...account(id).settings,...config};});DB.active=ids[0];persist();gate.show({players:selected.map(id=>player(id).name),difficulty:config.difficulty,modeLabel:config.mode+' · '+config.multiplayer,coop:config.multiplayer==='coop'},()=>{speech||=new SpellingSpeech({onStatus:text=>{if(/unavailable|could not/i.test(text))notify('Your device could not read this question. All written questions and hints remain available.');}});if(!account(ids[0]).tutorial)tutorial();else if(config.mode==='adventure')worlds();else begin();});};}
 function tutorial(){page='tutorial';tutorialStep=0;shell(`<div class="mq-tutorial mq-card"><h2>Try the controls · unscored tutorial</h2><p data-tutorial-text>1 · Your school grade chooses your skills. Try the grade selector.</p><label>School grade<select data-tutorial-grade>${options(SKILLS.map((_,g)=>[g,gradeLabel(g)]),grades[0])}</select></label><div class="mq-tutorial-row"><div><h3>2 + 3 = ?</h3><p>2 · Write or draw your idea on the paper. Your writing never submits an answer.</p><label>3 · Final answer<input data-example inputmode="numeric" placeholder="Enter 5"></label><button data-tutorial-hint>Hint</button><button data-tutorial-check class="mq-primary">Check Answer</button><p data-tutorial-feedback></p><button data-tutorial-finish hidden>LET’S EXPLORE →</button></div><div data-board></div></div></div>`);board=new MathBoard(q('[data-board]'),{ask});q('[data-tutorial-grade]').onchange=e=>{grades[0]=+e.target.value;account(ids[0]).grade=grades[0];};q('[data-tutorial-hint]').onclick=()=>q('[data-tutorial-feedback]').textContent='Start with two dots. Add three more dots, then count all five.';q('[data-tutorial-check]').onclick=()=>{if(q('[data-example]').value.trim()==='5'){q('[data-tutorial-feedback]').textContent='You did it! Hints and Show Me How help every question. In two-player mode, pass the screen after each answer and press Ready. Co-op shares one notebook and a team goal.';q('[data-tutorial-finish]').hidden=false;}else q('[data-tutorial-feedback]').textContent='Try counting 2 dots and 3 more dots. Enter 5 in the final answer box.';};q('[data-tutorial-finish]').onclick=()=>{account(ids[0]).tutorial=true;persist();boardStates=[null,null];if(config.mode==='adventure')worlds();else begin();};}
 function worldStats(i){const key=`${grades[0]}-${i}`;return account(ids[0]).worlds[key]||{stages:0,stars:0};}
 function worlds(){page='worlds';run=null;shell(`<div class="mq-map"><h2>${gradeLabel(grades[0])} · Your adventure map</h2><p>Earn three stages in each world. A stage needs at least 70% correct. Practice is always open.</p><div class="mq-world-grid">${WORLDS.map((w,i)=>{const s=worldStats(i),open=i===0||worldStats(i-1).stages>=3;return `<button data-world="${i}" ${open?'':'disabled'} style="--world:${w.color}">${mathWorldArt(i)}<h3>${w.name}</h3><b>${open?`${Math.min(3,s.stages)}/3 stages · ${s.stars} stars`:'Complete the previous world'}</b><small>${SKILLS[grades[0]].filter(s=>s.world===i).map(s=>s.label).join(' · ')||'Review and apply your grade’s skills'}</small></button>`;}).join('')}</div><button data-back>← Quest setup</button></div>`);host.querySelectorAll('[data-world]').forEach(el=>el.onclick=()=>{config.world=+el.dataset.world;begin();});q('[data-back]').onclick=setup;}
 function begin(){stopBoard();boardStates=[null,null];committed=false;elapsed=0;paused=false;feedback=null;const selected=ids.slice(0,config.multiplayer==='solo'?1:2);run=sessionFactory({grades:grades.slice(0,selected.length),count:config.count,mode:config.mode,multiplayer:config.multiplayer,difficulty:config.difficulty,skill:['practice','homework'].includes(config.mode)?config.skill:'mixed',subject:['practice','homework'].includes(config.mode)?config.subject:'all',world:config.world,progress:selected.map(id=>account(id))});run.next();question();}
 function activeIndex(){return run.turn;}
 function question(){page='question';hints=0;stage=0;hinted=false;answer='';feedback=null;speech?.cancel();const i=activeIndex(),p=run.players[i],quest=run.q,skill=skillById(quest.skill),name=config.multiplayer==='coop'?`Team · ${player(ids[i]).name}’s grade`:player(ids[i]).name;remaining=(quest.grade<=2?75:quest.grade<=5?100:130)+(quest.level*15);const timed=config.mode==='speed'&&config.timer;let keepState=boardStates[config.multiplayer==='coop'?0:i];if(!config.keepInk)keepState=null;
 shell(`<div class="mq-status"><strong>${esc(name)} · ${gradeLabel(quest.grade)}</strong><span>Question ${p.turns+1}/${config.count}${run.players.length>1?' each':''}</span><b data-score>${config.multiplayer==='coop'?'Team '+run.players.reduce((s,p)=>s+p.score,0):p.score} points</b><span data-clock>${timed?remaining+' seconds':'Take your time'}</span><button data-pause>Ⅱ Pause</button><progress value="${run.players.reduce((s,p)=>s+p.turns,0)}" max="${config.count*run.players.length}"></progress></div><div class="mq-play"><div class="mq-problem mq-card"><small>${esc(skill.label)} · ${esc(skill.code)}</small><h2>${esc(quest.prompt)}</h2><div class="mq-visual">${quest.visual?mathVisual(quest):''}</div><div data-interactive></div><div class="mq-speech"><button data-read>▶ Read Question</button><button data-repeat>↻ Repeat Question</button><button data-slow>Speak Slowly</button><button data-mute>${config.mute?'Unmute':'Mute voice'}</button></div><div class="learning-guide">${learningBadge()}<p>${mathAnswerGuide(quest)}</p></div><div class="mq-answer"><label for="mqAnswer">FINAL ANSWER${quest.unit?' · '+esc(quest.unit):''}</label><input id="mqAnswer" data-answer autocomplete="off" inputmode="text" aria-label="Final answer" placeholder="${quest.answerType==='pair'?'x,y':quest.type==='clock'?'H:MM':quest.answerType==='fraction'?'numerator/denominator':'Your answer'}"><div class="mq-choices"></div><div class="mq-keypad">${['7','8','9','4','5','6','1','2','3','−','0','.','/',',',':','e','⌫','C'].map(k=>`<button data-key="${k}" aria-label="${k==='⌫'?'Backspace':k==='C'?'Clear answer':k}">${k}</button>`).join('')}</div></div><div class="mq-learning"><button data-hint>Hint</button><button data-how>Show Me How</button><button data-check class="mq-primary">CHECK ANSWER</button></div><div class="mq-feedback" aria-live="polite"></div><div class="mq-explanation"></div><button data-next class="mq-primary" hidden>NEXT →</button></div><div class="mq-notebook"><h3>Your thinking space <small>Pen, shapes, ruler & fraction paper</small></h3><div data-board></div></div></div><div class="mq-pause" hidden></div>`);
 board=new MathBoard(q('[data-board]'),{ask,state:keepState,canDraw:()=>!paused&&page==='question'});boardStates[config.multiplayer==='coop'?0:i]=null;
 const setAnswer=v=>{if(run.phase!=='question'||paused)return;answer=String(v);q('[data-answer]').value=answer;};q('[data-answer]').oninput=e=>{if(run.phase==='question'&&!paused)answer=e.target.value;};q('[data-answer]').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit();}};host.querySelectorAll('[data-key]').forEach(el=>el.onclick=()=>{const k=el.dataset.key;setAnswer(k==='C'?'':k==='⌫'?answer.slice(0,-1):answer+(k==='−'?'-':k));});
 if(quest.choices){q('.mq-keypad').hidden=true;q('.mq-choices').innerHTML=quest.choices.map(v=>`<button data-choice="${esc(v)}">${esc(v)}</button>`).join('');host.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{setAnswer(el.dataset.choice);host.querySelectorAll('[data-choice]').forEach(b=>b.classList.toggle('selected',b===el));});}
 if(quest.type==='drag'){q('[data-interactive]').innerHTML='<div class="mq-drop" tabindex="0" aria-label="Drop your chosen number here">DROP THE MISSING NUMBER HERE</div>';const drop=q('.mq-drop');host.querySelectorAll('[data-choice]').forEach(el=>{el.onpointerdown=e=>{if(run.phase!=='question'||paused)return;e.preventDefault();el.setPointerCapture(e.pointerId);const ghost=el.cloneNode(true);ghost.className='mq-drag-ghost';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';document.body.append(ghost);drag={id:e.pointerId,value:el.dataset.choice,ghost};};el.onpointermove=e=>{if(drag?.id===e.pointerId){drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';}};el.onpointerup=e=>{if(drag?.id!==e.pointerId)return;const r=drop.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){setAnswer(drag.value);drop.textContent=drag.value;drop.classList.add('filled');}drag.ghost.remove();drag=null;};el.onpointercancel=()=>{drag?.ghost.remove();drag=null;};el.onclick=()=>{setAnswer(el.dataset.choice);drop.textContent=el.dataset.choice;drop.classList.add('filled');};});}
 if(quest.type==='numberline'){const v=quest.visual;q('[data-interactive]').innerHTML=`<label class="mq-numberline">Move to your number<input data-line type="range" min="${v.min}" max="${v.max}" value="0" step="1"><output data-lineval>0</output></label>`;q('[data-line]').oninput=e=>{setAnswer(e.target.value);q('[data-lineval]').textContent=e.target.value;q('.mq-visual').innerHTML=mathVisual({...quest,visual:{...v,target:+e.target.value}});};}
 if(quest.type==='clock'){q('.mq-keypad').hidden=quest.grade<=2;q('[data-interactive]').innerHTML=`<div class="mq-clock-entry"><label>Hour<select data-hour>${options(Array.from({length:12},(_,i)=>[i+1,i+1]),1)}</select></label><button data-minminus>−${quest.grade<=2?5:1} min</button><output data-minutes>00</output><button data-minplus>+${quest.grade<=2?5:1} min</button><button data-time>Use time</button></div>`;let minute=0;const clockValue=()=>`${q('[data-hour]').value}:${String(minute).padStart(2,'0')}`;q('[data-minminus]').onclick=()=>{minute=(minute+60-(quest.grade<=2?5:1))%60;q('[data-minutes]').textContent=String(minute).padStart(2,'0');setAnswer(clockValue());};q('[data-minplus]').onclick=()=>{minute=(minute+(quest.grade<=2?5:1))%60;q('[data-minutes]').textContent=String(minute).padStart(2,'0');setAnswer(clockValue());};q('[data-hour]').onchange=()=>setAnswer(clockValue());q('[data-time]').onclick=()=>setAnswer(clockValue());}
 const speak=rate=>{if(config.mute||DB.settings.muted){notify(DB.settings.muted?'Arcade audio is muted. Enable audio in arcade settings to hear questions.':'Voice is muted. Tap Unmute to read the question.');return;}const text=quest.prompt.replace(/□/g,' blank ').replace(/×/g,' times ').replace(/÷/g,' divided by ').replace(/−/g,' minus ').replace(/\^/g,' to the power of ').replace(/=/g,' equals ').replace(/\?/g,'');speech?.speak(text,{rate,replace:true});};q('[data-read]').onclick=()=>speak(.87);q('[data-repeat]').onclick=()=>speak(.87);q('[data-slow]').onclick=()=>speak(.73);q('[data-mute]').onclick=()=>{config.mute=!config.mute;speech?.cancel();q('[data-mute]').textContent=config.mute?'Unmute':'Mute voice';account(ids[0]).settings.mute=config.mute;persist();};q('[data-hint]').onclick=()=>{if(paused||run.phase!=='question')return;hinted=true;const hint=quest.hints[Math.min(hints++,quest.hints.length-1)];q('.mq-explanation').textContent='Hint '+Math.min(hints,quest.hints.length)+': '+hint;q('[data-hint]').textContent=hints<quest.hints.length?'Next hint':'Repeat hint';};q('[data-how]').onclick=()=>{hinted=true;q('.mq-explanation').innerHTML=quest.steps.slice(0,++stage).map((s,i)=>`<p><b>${i+1}.</b> ${esc(s)}</p>`).join('');if(stage>=quest.steps.length)q('[data-how]').textContent='Review all steps';};q('[data-check]').onclick=submit;q('[data-next]').onclick=next;q('[data-pause]').onclick=pause;
 }
 function submit(timeout=false){if(paused||run?.phase!=='question'||page!=='question')return;if(typeof timeout!=='boolean')timeout=false;if(!timeout&&!answer.trim()){notify('Choose or enter a final answer first. Your notebook is just for working.');return;}feedback=run.submit(answer,{hinted,timeout});if(!feedback)return;q('.mq-keypad').hidden=true;speech?.cancel();if(q('[data-score]'))q('[data-score]').textContent=(config.multiplayer==='coop'?'Team '+run.players.reduce((s,p)=>s+p.score,0):run.players[run.turn].score)+' points';persist();for(const el of host.querySelectorAll('.mq-answer button,.mq-answer input,[data-interactive] button,[data-interactive] input,[data-interactive] select,[data-check],[data-hint]'))el.disabled=true;q('.mq-feedback').className='mq-feedback '+(feedback.correct?'correct':'retry');q('.mq-feedback').textContent=feedback.correct?`★ You found it! +${feedback.points} points`:`${timeout?'Time to learn from this one.':'Good effort. Let’s work it through.'} Answer: ${fmt(feedback.answer)}${run.q.unit?' '+run.q.unit:''}`;q('.mq-explanation').innerHTML=run.q.steps.map((s,i)=>`<p><b>${i+1}.</b> ${esc(s)}</p>`).join('');q('[data-check]').hidden=true;q('[data-next]').hidden=false;const p=account(ids[run.turn]);if(p.correct>=100)unlock(player(ids[run.turn]),'math-hundred');if(run.players[run.turn].streak>=10)unlock(player(ids[run.turn]),'math-perfect');const mastery=Object.entries(p.skills).filter(([,s])=>s.status==='Mastered');if(mastery.some(([k])=>/add/.test(k)))unlock(player(ids[run.turn]),'math-addition');if(mastery.some(([k])=>/multiply/.test(k)))unlock(player(ids[run.turn]),'math-multiply');if(mastery.some(([k])=>/fraction/.test(k)))unlock(player(ids[run.turn]),'math-fraction');if(mastery.some(([k])=>/area|shape|angle|pythagoras|volume/.test(k)))unlock(player(ids[run.turn]),'math-geometry');persist();}
 function next(){if(run.phase!=='feedback')return;stopBoard();run.advance();if(run.phase==='finished'){results();return;}if(run.phase==='handoff'){handoff();return;}run.next();question();}
 function handoff(){page='handoff';speech?.cancel();shell(`<div class="mq-handoff mq-card"><div class="mq-up-icon">${config.multiplayer==='coop'?'🤝':'✦'}</div><h2>${config.multiplayer==='coop'?'Team, next quest!':`Player ${run.turn+1} — You’re Up!`}</h2><h3>${esc(player(ids[run.turn]).name)} · ${gradeLabel(grades[run.turn])}</h3><p>${config.multiplayer==='coop'?'A shared goal, with a question from this teammate’s grade.':'Pass the touchscreen. Your next question stays hidden until you are ready.'}</p><button data-ready class="mq-primary">READY!</button></div>`);q('[data-ready]').onclick=()=>{if(run.phase!=='handoff')return;run.ready();question();};}
 function pause(){if(page!=='question'||paused)return;paused=true;board?.cancel?.();q('.mq-play').inert=true;speech?.cancel();const pane=q('.mq-pause');pane.hidden=false;pane.innerHTML=`<div class="mq-card"><h2>Take a breath.</h2><p>The question timer is paused. Your writing and score are safe.</p><button data-resume class="mq-primary">RESUME</button><button data-review>How to Play</button><button data-quit>End session & return to setup</button></div>`;q('[data-resume]').onclick=()=>{paused=false;q('.mq-play').inert=false;pane.hidden=true;last=performance.now();};q('[data-review]').onclick=()=>gate.review();q('[data-quit]').onclick=async()=>{if(await ask('Return to setup? Completed answers stay in skill progress; this unfinished session earns no leaderboard result.')){paused=false;setup();}};}
 function stagePassed(i){const ps=run.players;return config.multiplayer==='coop'?ps.reduce((n,p)=>n+p.correct,0)/(config.count*ps.length)>=.7:ps[i].correct/config.count>=.7;}
 function results(){page='results';speech?.cancel();if(!committed){committed=true;const ps=run.players,winner=ps.length===1?0:ps[0].score===ps[1].score?-1:ps[0].score>ps[1].score?0:1;ps.forEach((p,i)=>{const a=account(ids[i]);a.bestScore=Math.max(a.bestScore,p.score);if(config.mode==='adventure'&&stagePassed(i)){const key=`${grades[i]}-${config.world}`,w=a.worlds[key]||{stages:0,stars:0};w.stages=Math.min(3,w.stages+1);w.stars+=p.correct;a.worlds[key]=w;if(w.stages===3)unlock(player(ids[i]),'math-world');}});if(config.mode!=='homework'){const entries=ps.map((p,i)=>({id:ids[i],score:p.score,hits:p.correct,errors:p.wrong,accuracy:Math.round(100*p.correct/Math.max(1,p.turns)),duration:elapsed,soloWin:stagePassed(i),details:{grade:grades[i],questions:p.turns,bestStreak:p.bestStreak,mode:config.mode}})),opts={game:'math',difficulty:{Easy:1,Normal:2,Hard:3,Adaptive:4}[config.difficulty],learn:true,mode:ps.length>1?'versus':'solo',winnerId:winner<0?null:ids[winner],ruleset:'math-quest-v1',levelId:config.mode,competition:config.multiplayer,challengeKey:`${grades.join('-')}-${config.count}-${config.timer?'timed':'untimed'}`};if(config.multiplayer==='coop')entries.forEach(e=>commitRound([e],{...opts,mode:'solo',winnerId:undefined}));else commitRound(entries,opts);}persist();}
 const ps=run.players,winner=ps.length===1?0:ps[0].score===ps[1].score?-1:ps[0].score>ps[1].score?0:1;const teamCorrect=ps.reduce((s,p)=>s+p.correct,0),ratio=teamCorrect/(config.count*ps.length),earned=ratio===1?3:ratio>=.7?2:ratio>=.4?1:0; shell(`<div class="mq-results mq-card"><div class="mq-stars">${"★".repeat(earned)+"☆".repeat(3-earned)}</div><h2>${config.multiplayer==='coop'?`${teamCorrect>=Math.ceil(config.count*ps.length*.7)?"Team goal reached!":"Team practice complete!"} ${teamCorrect} shared stars`:ps.length===1?'Look how far you’ve come!':winner<0?'A friendly tie!':esc(player(ids[winner]).name)+' wins!'}</h2><p>Every completed question adds to your personal learning journey.${config.multiplayer==='coop'?` Team goal: ${Math.ceil(config.count*ps.length*.7)} correct answers together.`:""}</p><div class="mq-result-grid">${ps.map((p,i)=>`<section><h3>${esc(player(ids[i]).name)} · ${gradeLabel(grades[i])}</h3><b>${p.score} points</b><p>${p.correct} correct · ${p.wrong} to practice · ${Math.round(100*p.correct/p.turns)}% accuracy</p><p>${p.turns} questions · Best streak ${p.bestStreak}</p><button data-player-progress="${i}">Review ${esc(player(ids[i]).name)}’s skills</button></section>`).join('')}</div>${config.mode==='adventure'?`<div class="mq-stage-results">${ps.map((p,i)=>`<p>${esc(player(ids[i]).name)} · ${gradeLabel(grades[i])} · ${WORLDS[config.world].name}: ${account(ids[i]).worlds[`${grades[i]}-${config.world}`]?.stages||0}/3 stages. ${stagePassed(i)?'Your stage is saved!':config.multiplayer==='coop'?'70% together unlocks the next stage.':'70% unlocks your next stage. Hints and practice can help.'}</p>`).join('')}</div>`:''}<div class="mq-buttons"><button data-again class="mq-primary">PLAY AGAIN</button><button data-setup>Quest setup</button><button data-parent>See progress</button>${config.mode==='adventure'?'<button data-map>World map</button>':''}</div></div>`);host.querySelectorAll('[data-player-progress]').forEach(el=>el.onclick=()=>{const i=+el.dataset.playerProgress;progress(ids[i],grades[i]);});q('[data-again]').onclick=begin;q('[data-setup]').onclick=setup;q('[data-parent]').onclick=()=>progress();if(q('[data-map]'))q('[data-map]').onclick=worlds;}
 function progress(selectedId=ids[0],selectedGrade=null){page='progress';const a=account(selectedId),g=selectedGrade??a.grade,skills=SKILLS[g];shell(`<div class="mq-progress mq-card"><h2>Every step counts</h2><label>Player<select data-progress-player>${options(DB.profiles.map(p=>[p.id,p.name]),selectedId)}</select></label><label>Review grade<select data-review-grade>${options(SKILLS.map((_,g)=>[g,gradeLabel(g)]),g)}</select></label><p><b>${gradeLabel(g)}</b> · ${a.correct} correct / ${a.answered} answered · ${a.answered?Math.round(a.correct/a.answered*100):0}% accuracy · ${a.stars} stars · Best ${a.bestScore} points</p><div class="mq-skill-grid">${skills.map(s=>{const p=a.skills[s.id];return `<section class="${p?.status==='Needs practice'?'needs':''}"><h3>${esc(s.label)}</h3><small>${s.code}</small><b>${p?.status||'Ready to explore'}</b><p>${p?`${p.correct}/${p.attempts} correct · ${p.independent} without hints · Level ${p.stage+1}`:'No attempts yet'}</p><button data-practice="${s.id}">Practice this skill</button></section>`;}).join('')}</div><details><summary>Curriculum & mastery</summary><p>Targeted practice follows the current North Carolina 2017 Mathematics SCOS. Newly adopted 2026 standards begin classroom implementation in 2028–29. Kindergarten repeating patterns are labeled enrichment. This game practices selected skills; it is not a complete school course.</p><p>Mastered: at least eight independent correct answers with 80% overall accuracy. Adaptive complexity increases gradually within each skill; mistakes trigger gentler review.</p><a href="${CURRICULUM_SOURCE}" target="_blank" rel="noopener">NC DPI standards reference</a></details><button data-back>BACK TO SETUP</button></div>`);q('[data-progress-player]').onchange=e=>progress(e.target.value);q('[data-review-grade]').onchange=e=>progress(selectedId,+e.target.value);host.querySelectorAll('[data-practice]').forEach(el=>el.onclick=()=>{ids[0]=selectedId;grades[0]=g;config.multiplayer='solo';config.mode='practice';config.subject='all';config.skill=el.dataset.practice;gate.show({players:[player(selectedId).name],difficulty:config.difficulty,modeLabel:'Practice'},()=>{speech||=new SpellingSpeech({onStatus:text=>{if(/unavailable|could not/i.test(text))notify('Your device could not read this question. All written questions and hints remain available.');}});if(!account(selectedId).tutorial)tutorial();else begin();});});q('[data-back]').onclick=setup;}
 const visibility=()=>{if(document.hidden){speech?.cancel();if(page==='question'&&!paused)pause();}};document.addEventListener('visibilitychange',visibility);
 function frame(now){if(disposed)return;const dt=Math.min(.1,(now-last)/1000);last=now;if(run?.phase==='question'&&page==='question'&&!paused){elapsed+=dt;if(config.mode==='speed'&&config.timer){remaining-=dt;if(q('[data-clock]'))q('[data-clock]').textContent=Math.max(0,Math.ceil(remaining))+' seconds';if(remaining<=0)submit(true);}}raf=requestAnimationFrame(frame);}
 if(initialPage==='records')progress();else setup();raf=requestAnimationFrame(frame);return()=>{disposed=true;cancelAnimationFrame(raf);stopBoard();drag?.ghost.remove();speech?.dispose();gate.dispose();document.removeEventListener('visibilitychange',visibility);host.innerHTML='';};
}
